// Circular Segmented Progress Tracker matching Image 1
export const SegmentedProgressTracker: React.FC<{
  percentage: number;
  size?: number;
  onClick?: () => void;
  className?: string;
}> = ({ percentage, size = 52, onClick, className = '' }) => {
  const totalSegments = 24;
  const radiusOuter = 26;
  const radiusInner = 19;
  const center = 28;
  const filledCount = Math.round((Math.max(0, Math.min(100, percentage)) / 100) * totalSegments);

  const segments = useMemo(() => {
    const list: Array<{ path: string; isFilled: boolean }> = [];
    const rad = Math.PI / 180;
    const segmentAngle = 360 / totalSegments;
    const gap = 2.4; // clean gap between segments

    for (let i = 0; i < totalSegments; i++) {
      // Start from 12 o'clock (-90 degrees) and rotate clockwise
      const startAngle = -90 + i * segmentAngle + gap / 2;
      const endAngle = -90 + (i + 1) * segmentAngle - gap / 2;

      const x1 = center + radiusOuter * Math.cos(startAngle * rad);
      const y1 = center + radiusOuter * Math.sin(startAngle * rad);
      const x2 = center + radiusOuter * Math.cos(endAngle * rad);
      const y2 = center + radiusOuter * Math.sin(endAngle * rad);
      const x3 = center + radiusInner * Math.cos(endAngle * rad);
      const y3 = center + radiusInner * Math.sin(endAngle * rad);
      const x4 = center + radiusInner * Math.cos(startAngle * rad);
      const y4 = center + radiusInner * Math.sin(startAngle * rad);

      const path = `M ${x1.toFixed(2)} ${y1.toFixed(2)} A ${radiusOuter} ${radiusOuter} 0 0 1 ${x2.toFixed(2)} ${y2.toFixed(2)} L ${x3.toFixed(2)} ${y3.toFixed(2)} A ${radiusInner} ${radiusInner} 0 0 0 ${x4.toFixed(2)} ${y4.toFixed(2)} Z`;

      list.push({
        path,
        isFilled: i < filledCount,
      });
    }
    return list;
  }, [totalSegments, filledCount]);

  return (
    <div
      onClick={onClick}
      role={onClick ? 'button' : undefined}
      title={`Profile ${percentage}% complete. Tap to complete missing info.`}
      className={`relative inline-flex items-center justify-center select-none active:scale-95 transition-transform cursor-pointer shrink-0 ${className}`}
      style={{ width: size, height: size }}
    >
      <svg
        viewBox="0 0 56 56"
        className="w-full h-full drop-shadow-xs"
        style={{ overflow: 'visible' }}
      >
        {segments.map((seg, idx) => (
          <path
            key={idx}
            d={seg.path}
            fill={seg.isFilled ? '#006C52' : '#BFE3DA'}
            className="transition-colors duration-300"
          />
        ))}
        {/* Center percentage label in bold dark teal */}
        <text
          x={center}
          y={center + 4.5}
          textAnchor="middle"
          fill="#006C52"
          fontSize="13"
          fontWeight="900"
          fontFamily="system-ui, -apple-system, sans-serif"
          letterSpacing="-0.5px"
        >
          {percentage}%
        </text>
      </svg>
    </div>
  );
};

