  // Profile completion calculation matching Image 1 (default 35% on fresh sign up)
  const profileCompletion = useMemo(() => {
    const rawName = (userProfile.name || '').trim();
    const isGeneric = !rawName || rawName.toLowerCase().includes('google') || rawName.toLowerCase().includes('apple') || rawName.toLowerCase().includes('haraka');
    const hasName = Boolean(rawName && !isGeneric);
    const hasEmail = Boolean(userProfile.email && userProfile.email.includes('@'));
    const hasPhone = Boolean(userProfile.phone && userProfile.phone.trim().length > 6);
    const hasAvatar = Boolean(userProfile.avatar);
    const hasLocation = Boolean(userProfile.location?.trim() || userProfile.city?.trim());
    const hasBio = Boolean(userProfile.bio?.trim());

    const items = [
      { id: 'email', title: 'Email Address', desc: userProfile.email || 'Add email', done: hasEmail, weight: 15 },
      { id: 'name', title: 'Full Legal Name', desc: hasName ? rawName : 'Add your full name', done: hasName, weight: 20 },
      { id: 'phone', title: 'Phone / WhatsApp', desc: userProfile.phone || 'Add phone number', done: hasPhone, weight: 20 },
      { id: 'avatar', title: 'Profile Photo', desc: hasAvatar ? 'Photo uploaded' : 'Upload photo', done: hasAvatar, weight: 20 },
      { id: 'location', title: 'Ghana Town / City', desc: userProfile.city || userProfile.location || 'Set your location', done: hasLocation, weight: 15 },
      { id: 'bio', title: 'About / Bio', desc: hasBio ? 'Bio added' : 'Add short bio', done: hasBio, weight: 10 },
    ];

    const score = items.filter((i) => i.done).reduce((acc, i) => acc + i.weight, 0);
    // 35% minimum on initial sign-up as shown in user Image 1
    const percentage = Math.min(100, Math.max(35, score));

    return { percentage, items };
  }, [userProfile]);

  // Clean profile name: NEVER show "Google User", "Apple User", or "Haraka User"
  const cleanProfileName = useMemo(() => {
    const raw = (userProfile.name || '').trim();
    const lower = raw.toLowerCase();
    if (!raw || lower.includes('google') || lower.includes('apple') || lower.includes('haraka')) {
      if (userProfile.email && userProfile.email.includes('@')) {
        const prefix = userProfile.email.split('@')[0];
        return prefix.charAt(0).toUpperCase() + prefix.slice(1);
      }
      return 'My Profile';
    }
    return raw;
  }, [userProfile.name, userProfile.email]);

